package claudecode

import (
	"bytes"
	"io"
	"testing"
)

// limitWriter accepts at most limit bytes of each Write and reports a short count with err.
type limitWriter struct {
	limit int
	err   error
	buf   bytes.Buffer
}

func (w *limitWriter) Write(b []byte) (int, error) {
	n := min(len(b), w.limit)
	w.buf.Write(b[:n])
	if n < len(b) {
		return n, w.err
	}
	return n, nil
}

// persist writes b and requires Write to accept all of it with no error.
func persist(t *testing.T, p *stderrPersistence, b string) {
	t.Helper()
	n, err := p.Write([]byte(b))
	if n != len(b) || err != nil {
		t.Errorf("Write(%q) = (%d, %v), want (%d, nil)", b, n, err, len(b))
	}
}

// requireState checks the retained output and the kept and lost counters.
func requireState(t *testing.T, p *stderrPersistence, retained string, got *bytes.Buffer, kept, lost int64) {
	t.Helper()
	if got.String() != retained {
		t.Errorf("retained = %q, want %q", got.String(), retained)
	}
	if p.kept != kept || p.lost != lost {
		t.Errorf("kept, lost = %d, %d, want %d, %d", p.kept, p.lost, kept, lost)
	}
}

func TestStderrPersistenceWriteCrossingCapAcceptsAllAndCountsOverflow(t *testing.T) {
	var single bytes.Buffer
	p := &stderrPersistence{w: &single, cap: 5}
	persist(t, p, "0123456789")
	requireState(t, p, "01234", &single, 5, 5)

	var multi bytes.Buffer
	p = &stderrPersistence{w: &multi, cap: 10}
	persist(t, p, "abcd")
	requireState(t, p, "abcd", &multi, 4, 0)
	persist(t, p, "efghijkl")
	requireState(t, p, "abcdefghij", &multi, 10, 2)
}

func TestStderrPersistenceShortWriteCountsUnwrittenAsLost(t *testing.T) {
	for name, err := range map[string]error{"no error": nil, "short write error": io.ErrShortWrite} {
		t.Run(name, func(t *testing.T) {
			w := &limitWriter{limit: 3, err: err}
			p := &stderrPersistence{w: w, cap: 100}
			persist(t, p, "abcdef")
			requireState(t, p, "abc", &w.buf, 3, 3)
			persist(t, p, "gh")
			requireState(t, p, "abcgh", &w.buf, 5, 3)
			persist(t, p, "ijklm")
			requireState(t, p, "abcghijk", &w.buf, 8, 5)
		})
	}
}

func TestStderrPersistenceWriteAfterCapExhaustedCountsFullLength(t *testing.T) {
	var got bytes.Buffer
	p := &stderrPersistence{w: &got, cap: 6}
	persist(t, p, "abcdef")
	requireState(t, p, "abcdef", &got, 6, 0)
	persist(t, p, "ghi")
	requireState(t, p, "abcdef", &got, 6, 3)
	persist(t, p, "jklmnop")
	requireState(t, p, "abcdef", &got, 6, 10)
}

